#include <iostream>
#include <cstdio>
#include <algorithm>
#include <string>
using namespace std;
const int N = 1e5 + 5;
int T;
int n;
string s, t, u, v;
int a[N][2], b[N][2];
int main() {
	cin >> T;
	for(int ti = 1; ti <= T; ti++) {
		cin >> n;
		cin >> s >> t >> u >> v;
		for(int i = 0; i < n; i++) a[i][0] = a[i][1] = b[i][0] = b[i][1] = 0;
		int beg = 0;
		for(int i = 0; i < n; i++) {
			if(u[i] == '0') continue;
			if(i > 0 && u[i - 1] == '0') beg = i;
			a[beg][s[i] - '0']++;
		}
		beg = 0;
		for(int i = 0; i < n; i++) {
			if(v[i] == '0') continue;
			if(i > 0 && v[i - 1] == '0') beg = i;
			b[beg][t[i] - '0']++;
		}
		int c[2] = {0, 0};
		int d[2] = {0, 0};
		int ans = 0;
		for(int i = 0; i < n; i++) {
			c[0] += a[i][0], c[1] += a[i][1], d[0] += b[i][0], d[1] += b[i][1];
			int o = 0;
			if(u[i] == '0' && v[i] == '0') ans += (s[i] == t[i]);
			else if(u[i] == '0') {
				o = s[i] - '0';
				if(d[o] > 0) ans++, d[o]--;
				else d[1 - o]--;
			} else if(v[i] == '0') {
				o = t[i] - '0';
				if(c[o] > 0) ans++, c[o]--;
				else c[1 - o]--;
			} else {
				if(c[0] > 0 && d[0] > 0) c[0]--, d[0]--, ans++;
				else if(c[1] > 0 && d[1] > 0) c[1]--, d[1]--, ans++;
				else {
					if(c[0] > 0) c[0]--;
					if(c[1] > 0) c[1]--;
					if(d[0] > 0) d[0]--;
					if(d[1] > 0) d[1]--; 
				}
			}
		}
		cout << ans << endl;
	}
	return 0;
}
